// Traduction simple ; {x} est remplacé par vars.x
export function makeT(lang) {
  const i = Math.max(0, LANGS.indexOf(lang));
  const t = (k) => (L[k] ? L[k][i] || L[k][0] : k);
  const tf = (k, v) => t(k).replace(/\{(\w+)\}/g, (_, x) => (v && v[x] != null ? v[x] : ''));
  return { t, tf };
}
